-- Atomic content revision invalidates resolved public data snapshots across requests.
INSERT OR IGNORE INTO cms_settings (name,value) VALUES ('site.revision',lower(hex(randomblob(16))));
CREATE TRIGGER IF NOT EXISTS hnaan_cache_jzw_article_ai AFTER INSERT ON `jzw_article` BEGIN UPDATE cms_settings SET value=lower(hex(randomblob(16))) WHERE name='site.revision'; END;
CREATE TRIGGER IF NOT EXISTS hnaan_cache_jzw_article_au AFTER UPDATE ON `jzw_article` BEGIN UPDATE cms_settings SET value=lower(hex(randomblob(16))) WHERE name='site.revision'; END;
